import fs from 'node:fs'
import path from 'node:path'

const repoRoot = process.cwd()
const preloadDir = path.join(repoRoot, 'src', 'preload')
const entryPath = path.join(preloadDir, 'index.mjs')
const outDir = path.join(preloadDir, 'generated')
const outPath = path.join(outDir, 'index.cjs')

function normalizeModuleId(value) {
  return String(value || '').replace(/\\/g, '/')
}

function readText(filePath) {
  return fs.readFileSync(filePath, 'utf8')
}

function findLocalPreloadRequires(sourceText) {
  const moduleIds = new Set()
  const pattern = /require\(['"](\.\/preload-[^'"]+\.cjs)['"]\)/g
  let match = pattern.exec(sourceText)
  while (match) {
    moduleIds.add(normalizeModuleId(match[1]))
    match = pattern.exec(sourceText)
  }
  return [...moduleIds].sort()
}

function buildModuleRegistry(moduleIds) {
  return moduleIds
    .map((moduleId) => {
      const modulePath = path.join(preloadDir, moduleId)
      const source = readText(modulePath)
      return `${JSON.stringify(moduleId)}: function(module, exports) {\n${source}\n}`
    })
    .join(',\n')
}

function buildBundle() {
  const entrySource = readText(entryPath)
  const moduleIds = findLocalPreloadRequires(entrySource)
  const moduleRegistry = buildModuleRegistry(moduleIds)
  const bundledEntry = entrySource.replace(
    /require\(['"](\.\/preload-[^'"]+\.cjs)['"]\)/g,
    (_match, moduleId) => `__preloadRequire(${JSON.stringify(normalizeModuleId(moduleId))})`,
  )

  return [
    "'use strict'",
    '// Generated by scripts/build-preload-bundle.mjs.',
    '// Electron sandboxed preload cannot require arbitrary sibling files.',
    'const __preloadModules = {',
    moduleRegistry,
    '}',
    'const __preloadCache = Object.create(null)',
    'function __preloadRequire(id) {',
    '  if (!Object.prototype.hasOwnProperty.call(__preloadModules, id)) return require(id)',
    '  if (__preloadCache[id]) return __preloadCache[id].exports',
    '  const module = { exports: {} }',
    '  __preloadCache[id] = module',
    '  __preloadModules[id](module, module.exports)',
    '  return module.exports',
    '}',
    bundledEntry,
    '',
  ].join('\n')
}

fs.mkdirSync(outDir, { recursive: true })
fs.writeFileSync(outPath, buildBundle(), 'utf8')
console.log(`Built ${path.relative(repoRoot, outPath).replace(/\\/g, '/')}`)
